<script lang="ts" module>import type { Snippet } from 'svelte'; export interface StepProps { title:string; description?:string; icon?:Snippet; disabled?:boolean; error?:boolean; optional?:boolean; children?:Snippet; }</script>
<script lang="ts">import { getStepsContext } from './context'; let {title,description,icon,disabled=false,error=false,optional=false,children}:StepProps=$props(); const ctx=getStepsContext(); const index=ctx.register({get title(){return title},get description(){return description},get icon(){return icon},get disabled(){return disabled},get error(){return error},get optional(){return optional}}); const state=$derived(ctx.state()); const status=$derived(error?'error':index<state.current?'completed':index===state.current?'current':'pending');</script>
<li class="rx-step rx-step--{state.variant}" class:rx-step--active={status==='current'} class:rx-step--complete={status==='completed'} class:rx-step--error={status==='error'} aria-current={status==='current'?'step':undefined} data-state={status}>
 <button type="button" disabled={disabled || !state.clickable} aria-label={`Step ${index+1}: ${title}`} onclick={()=>ctx.choose(index)}><span class="rx-step__mark">{#if icon}{@render icon()}{:else if status==='completed'}✓{:else}{index+1}{/if}</span><span class="rx-step__copy"><strong>{title}</strong>{#if optional}<small>Optional</small>{/if}{#if description}<span>{description}</span>{/if}</span></button>{#if children}<div class="rx-step__content">{@render children()}</div>{/if}
</li>
<style>
 .rx-step{position:relative;flex:1;min-width:0}.rx-step:not(:last-child)::after{content:'';position:absolute;left:2.5rem;right:-.2rem;top:1.05rem;height:2px;background:rgb(var(--rx-muted)/.35);z-index:0}.rx-step--complete:not(:last-child)::after{background:rgb(var(--rx-color))}.rx-step button{position:relative;z-index:1;display:flex;align-items:flex-start;gap:.65rem;border:0;background:transparent;color:inherit;text-align:left;padding:.25rem;cursor:pointer}.rx-step button:disabled{cursor:default}.rx-step__mark{display:grid;place-items:center;flex:none;width:2rem;height:2rem;border-radius:999px;background:rgb(var(--rx-muted)/.18);color:rgb(var(--rx-text));font-weight:700}.rx-step--active .rx-step__mark,.rx-step--complete .rx-step__mark{background:rgb(var(--rx-color));color:rgb(var(--rx-light))}.rx-step--error .rx-step__mark{background:rgb(var(--rx-danger));color:rgb(var(--rx-light))}.rx-step__copy{display:grid;gap:.15rem}.rx-step__copy span,.rx-step__copy small{font-size:.78rem;opacity:.65}.rx-step--pills button{border-radius:999px;background:rgb(var(--rx-muted)/.12);padding:.45rem .8rem}.rx-step--active.rx-step--pills button{background:rgb(var(--rx-color)/.12)}.rx-step--arrow button{border-radius:.4rem;background:rgb(var(--rx-muted)/.12)}.rx-step--bar .rx-step__mark{border-radius:.2rem;width:100%;height:.3rem;font-size:0}.rx-step--bar button{display:grid;width:100%}:global(.rx-steps--vertical) .rx-step:not(:last-child)::after{left:1.2rem;right:auto;top:2.3rem;bottom:-.2rem;width:2px;height:auto}.rx-step__content{padding:1rem 2.9rem}@media(max-width:640px){.rx-step__copy span{display:none}}
</style>
